    "corpo": [
      "A ação penal militar é, em regra, sempre pública incondicionada — diferente do processo penal comum, que admite ação privada e pública condicionada em determinadas hipóteses, no âmbito militar o Ministério Público Militar é o titular exclusivo da ação penal para todos os crimes militares, sem depender de representação da vítima ou de qualquer outra condição de procedibilidade.",
      "O Ministério Público Militar, ramo especializado do Ministério Público da União, atua exclusivamente perante a Justiça Militar da União (que julga crimes militares praticados por integrantes das Forças Armadas) — importante notar que, no caso das Polícias Militares estaduais, a ação penal para os crimes militares estaduais é promovida pelo Ministério Público estadual, perante a Justiça Militar estadual (nos estados que a possuem como órgão de primeira instância) ou perante o próprio Tribunal de Justiça, conforme a organização judiciária de cada estado.",
      "A denúncia na ação penal militar segue estrutura semelhante à denúncia do processo penal comum, narrando o fato criminoso com suas circunstâncias, a qualificação do acusado, a classificação do crime, e o rol de testemunhas — o oferecimento da denúncia dá início à ação penal, inaugurando a fase processual propriamente dita perante o órgão da Justiça Militar competente."
    ],
    "pontosChave": [
      "Ação penal militar é sempre pública incondicionada — não existe ação penal privada ou condicionada no âmbito militar.",
      "Ministério Público Militar (da União) atua perante a Justiça Militar da União (Forças Armadas); crimes de PM estadual são de competência do MP estadual.",
      "Denúncia militar segue estrutura semelhante à denúncia comum, narrando fato, qualificação, classificação e rol de testemunhas."
    ],
