        "texto": "Diferente do homicídio doloso (já deslocado expressamente para a Justiça comum), outros crimes militares que tenham civil como vítima (lesão corporal, por exemplo) podem, a depender da legislação e jurisprudência vigente no momento, permanecer sob competência da Justiça Militar ou também ter sua competência questionada — esse é um tema de contínua evolução legislativa e jurisprudencial, que exige atenção a atualizações."
