      "Polícia judiciária militar é a função exercida por autoridades militares (comandantes, chefes, diretores de unidades e organizações militares) na apuração de crimes militares, com atribuições semelhantes às da polícia judiciária comum (já estudada), mas exercida dentro da própria estrutura hierárquica militar, não por uma corporação policial civil especializada em investigação.",
