        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Conselho de Justiça: Especial e Permanente\", a ideia principal é: O julgamento de crimes militares em primeira instância é realizado por um órgão colegiado chamado Conselho de Justiça, composto por um juiz togado (civil, com formação jurídica, que preside o Conselho) e por oficiais militares (juízes militares temporários. Para estudar sem travar, guarde primeiro estas palavras-chave: Conselho Especial de Justiça, Conselho Permanente de Justiça, juiz militar. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Conselho Especial julga oficiais (formado por processo, dissolvido depois); Conselho Permanente julga praças (composição mais estável).",
