      "Apelação é o principal recurso cabível contra a sentença proferida pelo Conselho de Justiça (Especial ou Permanente), seguindo lógica semelhante à apelação do processo penal comum — busca a reforma ou anulação da decisão de primeira instância, sendo julgada pelo órgão de segunda instância competente.",
