      "Embargos infringentes e de nulidade são recursos cabíveis, no processo penal militar, contra decisões não unânimes de segunda instância que sejam desfavoráveis ao acusado — buscando novo julgamento, agora com composição mais ampla, quando há divergência entre os julgadores do órgão colegiado de segunda instância, refletindo preocupação adicional de garantia ao acusado diante de decisões não consensuais na revisão do caso."
