      "A execução penal militar trata do cumprimento efetivo das penas aplicadas em processo penal militar — seguindo, em linhas gerais, princípios semelhantes aos já estudados na execução penal comum (individualização da pena, respeito à dignidade do condenado, possibilidade de progressão conforme a espécie de pena), mas com o cumprimento ocorrendo, em regra, em estabelecimento penal militar específico, distinto do sistema penitenciário civil.",
