      "A guia de recolhimento militar formaliza o início do cumprimento da pena privativa de liberdade imposta em processo militar, documentando os dados essenciais da condenação (pena aplicada, regime, tempo já cumprido, se houver) — instrumento com função equivalente à guia de recolhimento do processo penal comum, adaptado à estrutura e ao estabelecimento penal militar específico onde a pena será cumprida."
